/**
 * Dev-only sample boot data: `viewer.html?fixture=<name>` (see FIXTURE_NAMES).
 * main.tsx imports this behind `import.meta.env.DEV`, so it is dropped from production
 * builds. It writes the same DOM the worker will, so the real boot path is exercised.
 * Media files come from web/fixtures/ (generated by `npm run fixtures`), which the dev
 * server serves at /fixtures/.
 */

import type { FileData } from './types';

export const FIXTURE_NAMES = [
  'image',
  'file',
  'pdf',
  'pdf-password',
  'missing',
  'unavailable',
  'home',
  'convert',
  'album-grid',
  'album-list',
  'album-tracklist',
] as const;
export type FixtureName = (typeof FIXTURE_NAMES)[number];

const HOUR = 60 * 60 * 1000;
const DAY = 24 * HOUR;

interface Fixture {
  page?: string;
  state?: string;
  /** undefined: no script tag. null: the literal `null` payload. */
  file?: FileData | null;
  album?: Record<string, unknown>;
}

const fx = (name: string) => `${location.origin}/fixtures/${name}`;

function fixtures(now: number): Record<FixtureName, Fixture> {
  const pdf: FileData = {
    kind: 'pdf',
    filename: 'files-gg-sample.pdf',
    mimetype: 'application/pdf',
    extension: 'pdf',
    size: 17_113,
    cdnUrl: fx('sample.pdf'),
    url: 'https://files.gg/pdf123.pdf',
    media: { pages: 8 },
    thumbnail: { url: fx('pdf-thumb.png'), type: 'thumb', width: 240, height: 310 },
    uploadedAt: now - 5 * HOUR,
    expiresAt: null,
  };

  const photo = (n: number, width: number, height: number, caption: string, extra: Partial<FileData> = {}) => ({
    kind: 'image',
    filename: `photo-${n}.png`,
    mimetype: 'image/png',
    extension: 'png',
    size: 8000 + n * 731,
    width,
    height,
    cdnUrl: fx(`photo-${n}.png`),
    url: `https://files.gg/ph${n}.png`,
    uploadedAt: now - (10 - n) * HOUR,
    expiresAt: null,
    caption,
    ...extra,
  });

  const track = (n: number, title: string, duration: number, cover: string) => ({
    kind: 'audio',
    filename: `${String(n).padStart(2, '0')} ${title}.wav`,
    mimetype: 'audio/wav',
    extension: 'wav',
    size: 24_000 + n * 8000,
    duration,
    cdnUrl: fx(`tone-${n}.wav`),
    url: `https://files.gg/tr${n}.wav`,
    media: { duration, tags: { title, artist: 'The Placeholders', album: 'Test Tones', track: n } },
    thumbnail: { url: fx(cover), type: 'cover', width: 400, height: 400 },
    uploadedAt: now - DAY,
    expiresAt: null,
    caption: '',
  });

  return {
    image: {
      page: 'file',
      state: 'file',
      file: {
        kind: 'image',
        filename: 'og-image.png',
        mimetype: 'image/png',
        extension: 'png',
        size: 507_507,
        width: 1200,
        height: 630,
        cdnUrl: `${location.origin}/og-image.png`,
        url: 'https://files.gg/abc123.png',
        uploadedAt: now - 3 * DAY,
        expiresAt: now + 5 * HOUR,
      },
    },
    file: {
      page: 'file',
      state: 'file',
      file: {
        kind: 'file',
        filename: 'project-backup-2026-11-24.zip',
        mimetype: 'application/zip',
        extension: 'zip',
        size: 48_234_112,
        cdnUrl: `${location.origin}/favicon.ico`,
        url: 'https://files.gg/xyz789.zip',
        uploadedAt: now - 2 * HOUR,
        expiresAt: null,
      },
    },
    pdf: { page: 'file', state: 'file', file: pdf },
    'pdf-password': {
      page: 'file',
      state: 'file',
      file: { ...pdf, filename: 'protected.pdf', cdnUrl: fx('sample-protected.pdf'), size: 17_462, thumbnail: undefined },
    },
    missing: { page: 'file', file: null },
    unavailable: { page: 'file', state: 'unavailable' },
    home: { page: 'home' },
    convert: { page: 'convert' },
    'album-grid': {
      page: 'album',
      state: 'album',
      album: {
        vanity: 'demo1234',
        url: 'https://files.gg/a/demo1234',
        title: 'Weekend trip',
        description:
          'Photos, a clip and the itinerary from the weekend.\nMap and tickets: https://example.com/trip-notes (opens outside files.gg).',
        layout: 'grid',
        nsfw: false,
        expires_at: now + 6 * DAY,
        created_at: now - 2 * DAY,
        items: [
          photo(1, 800, 500, 'Arriving at the coast'),
          photo(2, 400, 600, 'The lighthouse'),
          {
            kind: 'video',
            filename: 'screen-recording.mkv',
            mimetype: 'video/x-matroska',
            extension: 'mkv',
            size: 18_400_000,
            width: 640,
            height: 360,
            duration: 12_000,
            cdnUrl: fx('missing-video.mkv'),
            url: 'https://files.gg/vid1.mkv',
            media: { width: 640, height: 360, duration: 12_000, playable: false, codecs: ['hevc'] },
            thumbnail: { url: fx('video-poster.png'), type: 'poster', width: 640, height: 360 },
            uploadedAt: now - 9 * HOUR,
            expiresAt: null,
            caption: 'Drone clip (HEVC, so it downloads instead of playing)',
          },
          photo(3, 600, 600, ''),
          { ...pdf, caption: 'Itinerary' },
          photo(4, 1000, 350, 'Panorama from the hill'),
          photo(5, 600, 400, 'Dinner'),
          {
            kind: 'file',
            filename: 'tickets.zip',
            mimetype: 'application/zip',
            extension: 'zip',
            size: 144,
            cdnUrl: fx('archive.zip'),
            url: 'https://files.gg/zip1.zip',
            uploadedAt: now - 8 * HOUR,
            expiresAt: null,
            caption: 'Tickets',
          },
        ].map((item, position) => ({ ...item, position })),
      },
    },
    'album-list': {
      page: 'album',
      state: 'album',
      album: {
        vanity: 'list5678',
        url: 'https://files.gg/a/list5678',
        title: 'Comic, part 1',
        description: 'Read top to bottom.',
        layout: 'list',
        nsfw: false,
        expires_at: null,
        items: [photo(2, 400, 600, 'Page 1'), photo(1, 800, 500, 'Page 2'), photo(5, 600, 400, 'Page 3'), { ...pdf, caption: 'Bonus: the script' }].map(
          (item, position) => ({ ...item, position }),
        ),
      },
    },
    'album-tracklist': {
      page: 'album',
      state: 'album',
      album: {
        vanity: 'tone9012',
        url: 'https://files.gg/a/tone9012',
        title: '',
        description: 'Three short test tones, generated for the fixture.',
        layout: 'auto',
        nsfw: false,
        expires_at: null,
        cover: { url: fx('cover-1.png'), type: 'cover', width: 400, height: 400 },
        items: [
          track(1, 'A Four Forty', 4000, 'cover-1.png'),
          track(2, 'C Five', 3000, 'cover-2.png'),
          track(3, 'E Five', 5000, 'cover-1.png'),
        ].map((item, position) => ({ ...item, position })),
      },
    },
  };
}

export function isFixtureName(value: string | null): value is FixtureName {
  return value !== null && (FIXTURE_NAMES as readonly string[]).includes(value);
}

/** Dev convenience: the fixture a path implies when no `?fixture=` is given. */
export function fixtureForPath(pathname: string): FixtureName | null {
  if (pathname === '/convert') return 'convert';
  if (/^\/a\/[^/]+/.test(pathname)) return 'album-grid';
  return null;
}

/** Injects a fixture into the document the way the worker would. */
export function applyFixture(name: FixtureName, doc: Document = document, now = Date.now()): void {
  const fixture = fixtures(now)[name];
  const root = doc.getElementById('root');
  if (!root) return;
  if (fixture.page) root.dataset.page = fixture.page;
  if (fixture.state) root.dataset.state = fixture.state;

  doc.getElementById('file-data')?.remove();
  doc.getElementById('album-data')?.remove();
  const inline = (id: string, value: unknown) => {
    const script = doc.createElement('script');
    script.id = id;
    script.type = 'application/json';
    script.textContent = JSON.stringify(value);
    root.after(script);
  };
  if (fixture.file !== undefined) inline('file-data', fixture.file);
  if (fixture.album !== undefined) inline('album-data', fixture.album);
}
